    var onFlip: (() -> Void)?
    func prepare() { onFlip = { [weak self] in print(self?.id ?? 0) } }
    deinit { print("Карточка освобождена") }
}
func check() -> Bool {
    var card: RuleCard? = RuleCard()
    weak var observer = card
    card!.prepare()
    card = nil
    return observer == nil
}
print([check(), check(), check()])

Три сообщения «Карточка освобождена», затем [true, true, true]. Проверка не становится владельцем экземпляров.

