final class FoldTip {
    let id: Int
    init(id: Int) { self.id = id }
    deinit { print("Подсказка \(id) освобождена") }
}
var history: [FoldTip] = []
func keep(_ tip: FoldTip) {
    history.append(tip)
    if history.count > 2 { history.removeFirst() }
}
var first: FoldTip? = FoldTip(id: 1)
weak var observer = first
keep(first!)
first = nil
keep(FoldTip(id: 2))
keep(FoldTip(id: 3))
print(observer == nil)
print(history.count)
history.removeAll()

До финальной уборки: «Подсказка 1 освобождена», true, 2. Затем освобождаются оставшиеся подсказки; порядок их deinit не является условием задачи. Ограничен объём достижимой истории.
